import { Hatchet } from "@hatchet-dev/typescript-sdk";

export const hatchet = new Hatchet();

const runId = process.env.ZEALT_RUN_ID || 'default-run-id';

export const workflow = hatchet.workflow({
  name: `linear-dag-${runId}`,
});

export const step1 = workflow.task({
  name: "step1",
  fn: async (ctx) => {
    return { text: "hello" };
  },
});

export const step2 = workflow.task({
  name: "step2",
  parents: [step1],
  fn: async (ctx) => {
    const parent = await ctx.parentOutput(step1);
    return { text: parent.text + " world" };
  },
});

export const step3 = workflow.task({
  name: "step3",
  parents: [step2],
  fn: async (ctx) => {
    const parent = await ctx.parentOutput(step2);
    return { final: parent.text + "!" };
  },
});

import { hatchet, workflow } from "./workflow.js";

const runId = process.env.ZEALT_RUN_ID || 'default-run-id';

async function main() {
  const worker = hatchet.worker(`linear-dag-worker-${runId}`, {
    workflows: [workflow],
  });
  await worker.start();
}

main().catch(console.error);

import { workflow } from "./workflow.js";
import * as fs from "fs";

async function main() {
  const run = await workflow.run({});
  const result = await run.result();

  const step3Output = result.step3 || result;

  fs.writeFileSync("/tmp/result.json", JSON.stringify(step3Output, null, 2));
  process.exit(0);
}

main().catch(console.error);

import { workflow } from "./workflow.js";
import * as fs from "fs";

async function main() {
  const run = await workflow.run({});
  const result = await run.result();

  console.log("DAG Result:", JSON.stringify(result, null, 2));

  const step3Output = result.step3 || result;

  fs.writeFileSync("/tmp/result.json", JSON.stringify(step3Output, null, 2));
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

