import { Hatchet } from "@hatchet-dev/typescript-sdk/v1";

export const hatchet = new Hatchet();

const runId = process.env.ZEALT_RUN_ID || 'default-run-id';

export const workflow = hatchet.workflow({
  name: `linear-dag-${runId}`,
});

